{"code":"# Search for a linear checksum letter formula
# letter_value = (p*L1+q*L2+a*d1+b*d2+c*d3 + k) mod 26, map 1..26 -> A..Z (0->Z)
# Need 18 (R) for QT456 and XY001; for AB123 need != 24 (X) if X is the invalid letter.

def val(letters):
    return [ord(c)-64 for c in letters]

sols=[]
for p in range(-3,4):
  for q in range(-3,4):
    for a in range(-3,4):
      for b in range(-3,4):
        for c in range(-3,4):
          for k in range(0,26):
            def cv(L,d):
                lv=val(L)
                v=p*lv[0]+q*lv[1]+a*d[0]+b*d[1]+c*d[2]+k
                v%=26
                if v==0: v=26
                return v
            r1=cv("QT",[4,5,6])
            r2=cv("XY",[0,0,1])
            r3=cv("AB",[1,2,3])
            if r1==18 and r2==18 and r3!=24:
                sols.append((p,q,a,b,c,k,r3))
print(len(sols))
for s in sols[:30]:
    print(s)"}

